"use strict";(globalThis.webpackChunkgrc||=[]).push([[3031],{38216(e){e.exports=JSON.parse('{"citeKey":"yildirim2026gdsight","slug":"yildirim-2026-gdsight-4e6a","title":"GDSight: Per-Operation Cross-Layer Attribution for GPUDirect Storage","authors":["I. Yildirim","X.-H. Sun","A. Kougkas"],"venue":"11th International Parallel Data Systems Workshop (PDSW 2026), held in conjunction with SC26","type":"Workshop","entryType":"inproceedings","date":"November, 2026","year":2026,"era":"iit","month":11,"abstract":"GPUDirect Storage (GDS) copies NVMe data into GPU memory, bypassing the CPU data path and the identity linking an operation to the device work it causes. To our knowledge, no external GDS tool attributes a device command to its causing application operation: cuFile stops at the call, counters report only aggregates, and time-based matching fails once submission is asynchronous, even at one operation in flight. We present GDSight, which attributes each NVMe command to the operation that caused it, whether it entered cuFile or fell back to POSIX. Using eBPF, it matches commands by timing and by physical address, and only address survives asynchrony. On unmodified KvikIO, NIXL and HDF5 we pin pathologies to their cause: a silent bypass cuFile\'s counters miss, 4\xd7 device amplification, and 22\xd7 tail inflation. We show that each diagnosis resolves to a measured intervention, worth up to 17\xd7 where throughput is the limit, or none.","hasAbstract":true,"lede":"We present GDSight, which attributes each NVMe command to the operation that caused it, whether it entered cuFile or fell back to POSIX.","links":{"code":"https://github.com/izzet/gdsight","artifact":"https://doi.org/10.5281/zenodo.22718932","program":"https://sc26.conference-program.com/presentation/?id=ws_pdsw125&sess=sess129"},"tags":["GPUDirect Storage","cuFile","NVMe","eBPF","Cross-Layer I/O Tracing","Per-Operation Attribution","Explainability"],"_projectIds":[],"grcSelected":false,"status":"accepted","visibility":"public","projectIds":[],"memberAuthors":["yildirim-izzet","sun-xian-he","kougkas-anthony"]}')}}]);